import{at as e,it as t,n,vt as r}from"./chunks/framework.fhiXEbOi.js";var i=JSON.parse(`{"title":"Escrow deployment settings","description":"Escrow-specific contract ownership, CAM handover and acceptance checks; use the shared release procedure for execution.","frontmatter":{"title":"Escrow deployment settings","description":"Escrow-specific contract ownership, CAM handover and acceptance checks; use the shared release procedure for execution.","outline":false},"headers":[],"relativePath":"deployment/escrow/index.md","filePath":"deployment/escrow/index.md"}`),a={name:`deployment/escrow/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="escrow-deployment-settings" tabindex="-1">Escrow deployment settings <a class="header-anchor" href="#escrow-deployment-settings" aria-label="Permalink to “Escrow deployment settings”">​</a></h1><div class="ported-guide"><p>Use <a href="../new-instance.html">Deploy a new instance</a>, substituting the <code>escrow</code> app prefix. This page covers Escrow&#39;s choices and acceptance checks, not a second release procedure.</p><h2 id="release-deployment">Choose who controls publication</h2><table><thead><tr><th>Contract</th><th>Authority after deployment</th></tr></thead><tbody><tr><td><code>CamEscrow</code></td><td>Immutable business rules; no owner, pause, upgrade, fee, sweep or administrator recovery.</td></tr><tr><td><code>CamEscrowUI</code></td><td>Read-only projection with an immutable backing contract. No write-forwarding or ownership role.</td></tr><tr><td><code>CamRoot</code></td><td>The current owner controls the manifest URI/hash and contract bindings.</td></tr></tbody></table><p>Choose <code>INTENDED_CAM_ROOT_OWNER</code> deliberately. The publication signer can nominate a different owner; that nominee must separately call <code>acceptOwnership()</code> on the root address in the final CAM publication artifact. There is no CAM acceptance delay. The current owner remains authorized until acceptance.</p><p>The client chooses contractor, arbitrator, terms and durations when creating each agreement; these are not deployment-wide default authorities. An arbitrator never acknowledges participation on chain before funding.</p><p>Business creation, projection deployment and CAM publication can use separate actors and source selections. Keep <a href="../../reference/operations.html">their retained inputs and artifacts</a>. Host the prepared files before approving their root publication, using the shared procedure&#39;s hosting pause.</p><h2 id="release-verification">Accept the instance, not just its records</h2><p>Run <code>escrow/release/verify</code> with the same selected context and instance to check historical deployment evidence. It sends no transaction and preserves final records. A recorded pending nomination is valid evidence, not proof that today&#39;s handover completed.</p><p>For current acceptance, confirm the intended root&#39;s <code>owner()</code> and zero <code>pendingOwner()</code>, its exact publication/resources, and the expected business/projection bindings. Open a known read in a compatible viewer. Never infer agreement status or solvency from a successful historical verifier.</p><p>To change the projection or workflow later, use <a href="../update.html">the appropriate update path</a>. A missing artifact after successful execution belongs in <a href="../recovery.html">recovery</a>, not another contract creation.</p><h2 id="operational-monitoring">Observe the boundaries that can change</h2><p>Monitor root ownership nominations/acceptance and <code>CamUpdated</code>/<code>ContractAddressSet</code>. On the business contract, track agreement creation/state changes, withdrawals, outstanding deadlines and <code>totalLiabilities()</code> against its native balance.</p><p>No component automatically executes expired agreements. Someone must send the appropriate timeout transaction; disputes also depend on the selected arbitrator being available before their deadline. Settlement credit still requires a beneficiary withdrawal.</p><p><a href="../../escrow/">User workflow</a> · <a href="../../viewer/">Host the viewer</a> · <a href="../source-verification.html">Publish original sources</a>. Implementation: <a href="https://github.com/numpde/dapp32/tree/04a18763700bbaa25cad73b9806d236ab4d5e139/dapps/escrow">source 04a18763</a>.</p></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};